const d=[{id:"M01",title:"Ryan y Deci · 2000 · Teoría de la autodeterminación",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"La motivación puede responder a valores que haces tuyos sin disfrutar la tarea. La teoría propone autonomía, competencia y conexión con otros como necesidades básicas.",limitation:"Teoría y revisión narrativa, no ensayo de las preguntas de ODA. Autonomía no es independencia; premios y obligaciones no vuelven ajena una meta automáticamente."},{id:"M02",title:"Ntoumanis y colaboradores · 2021 · Intervenciones de salud que apoyan necesidades",url:"https://selfdeterminationtheory.org/wp-content/uploads/2020/05/2020_NtoumanisEtAl_MetaAnalysisHealth.pdf",type:"research",finding:"73 estudios mostraron beneficios promedio modestos en motivación autónoma y conductas de salud posteriores. La mejoría inmediata de salud física no fue estadísticamente significativa.",limitation:"Programas de salud con varios apoyos, gran diversidad y limitaciones de diseño. Una pregunta sobre valores no reproduce el programa ni demuestra efectos para todas las metas."},{id:"M03",title:"Duckworth y colaboradores · 2013 · Protocolo académico de MCII",url:"https://www.researchgate.net/publication/256294319_From_Fantasy_to_Action_Mental_Contrasting_With_Implementation_Intentions_MCII_Improves_Academic_Performance_in_Children",type:"research",finding:"Un ensayo con 77 alumnos de quinto grado usó tres sesiones de una hora en grupos pequeños y planes repetidos de resultado, obstáculo y respuesta. Mejoraron algunos resultados académicos.",limitation:"Una escuela, diferencias posteriores entre grupos no significativas y apoyo y duración específicos para niños. No hay efecto establecido para un ejercicio breve de adultos por teléfono."},{id:"M04",title:"Cerasoli, Nicklin y Ford · 2014 · Motivación e incentivos",url:"https://selfdeterminationtheory.org/wp-content/uploads/2017/06/2014_Cerasoli_Intrinsic.pdf",type:"research",finding:"En 183 muestras, tanto la motivación intrínseca como los incentivos se relacionaron con el desempeño, con patrones distintos para calidad y cantidad.",limitation:"Resultados correlacionales y diversos. No demuestran recomendaciones universales sobre premios ni que las metas con reconocimiento social sean ajenas a quien las persigue."},{id:"M05",title:"Lally y colaboradores · 2010 · Modelar la formación de hábitos",url:"https://www.flexyourbrain.com/wp-content/uploads/2015/10/UL-STUDY-66-Days-IJSP_998-1009.pdf",type:"research",finding:"Entre 39 curvas bien ajustadas, la mediana estimada por el modelo para alcanzar el 95 por ciento de la meseta de automatización fue 66 días. Perder una ocasión no alteró sustancialmente el proceso modelado.",limitation:"Se observó durante 84 días; 254 días fue una extrapolación. No son fechas observadas de finalización, un calendario universal ni evidencia sobre interrupciones largas."},{id:"M07",title:"Wood y Rünger · 2016 · Psicología del hábito",url:"https://dornsife.usc.edu/wendy-wood/wp-content/uploads/sites/183/2023/10/wood.runger.2016.pdf",type:"research",finding:"Los contextos recurrentes y las respuestas repetidas pueden apoyar el aprendizaje de hábitos; las metas deliberadas y las acciones habituales pueden coexistir.",limitation:"Revisión narrativa, no ensayo del mínimo o receta de ODA. Las señales no garantizan actuar; las acciones pequeñas no necesariamente crecen."},{id:"M08",title:"Gollwitzer y Sheeran · 2006 · Planes si-entonces",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"Los planes si-entonces específicos mejoraron el logro de metas en promedio en 94 pruebas independientes. El efecto estandarizado histórico fue d = 0.65.",limitation:"Evidencia antigua y diversa. No significa mejorar un 65 por ciento, ejecución garantizada ni un parámetro para un recordatorio de la app."},{id:"M10",title:"Wang, Wang y Gai · 2021 · Contraste mental y planificación",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 artículos y 24 efectos independientes mostraron beneficios promedio pequeños a moderados para alcanzar metas con planes de resultado, obstáculo y respuesta.",limitation:"La diversidad y señales de sesgo de publicación limitan la magnitud. No garantiza deseos ni demuestra que pensar cambie acontecimientos externos ni valida todo formato WOOP."},{id:"M13",title:"Harkin y colaboradores · 2016 · Seguimiento del progreso",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"Las intervenciones de seguimiento mejoraron el logro de metas en promedio en 138 estudios aleatorizados.",limitation:"Metas y métodos diversos. Las asociaciones de moderadores no aíslan efectos causales de registrar o compartir; no establecen una frecuencia semanal óptima ni exigen compartir públicamente."},{id:"M15",title:"Fogg · Instrucciones de diseño de Tiny Habits",url:"https://tinyhabits.com/design/",type:"technique",finding:"La receta de este método une una rutina existente y una acción muy pequeña. Recomienda revisar las combinaciones que no funcionan.",limitation:"Esta página no ofrece estimaciones controladas que validen toda la receta, celebrar obligatoriamente, una duración óptima menor a un minuto ni crecimiento inevitable."},{id:"M20",title:"NIMH · Cuidar tu salud mental",url:"https://www.nimh.nih.gov/health/topics/caring-for-your-mental-health",type:"guidance",finding:"Los síntomas persistentes graves o angustiosos, la pérdida de interés o no poder realizar actividades habituales justifican ayuda profesional. El peligro urgente requiere ayuda inmediata.",limitation:"Guía pública, no ensayo de eficacia de ODA ni diagnóstico por poca motivación. Si algo preocupa, no tienes que esperar dos semanas, una racha ni terminar el curso."},{id:"motivation-sdt",title:"Ryan y Deci · 2000 · Teoría de la autodeterminación",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"La motivación puede responder a valores que haces tuyos sin disfrutar la tarea. La teoría propone autonomía, competencia y conexión con otros como necesidades básicas.",limitation:"Teoría y revisión narrativa, no ensayo de las preguntas de ODA. Autonomía no es independencia; premios y obligaciones no vuelven ajena una meta automáticamente."},{id:"motivation-sdt-meta",title:"Ntoumanis y colaboradores · 2021 · Intervenciones de salud que apoyan necesidades",url:"https://selfdeterminationtheory.org/wp-content/uploads/2020/05/2020_NtoumanisEtAl_MetaAnalysisHealth.pdf",type:"research",finding:"73 estudios mostraron beneficios promedio modestos en motivación autónoma y conductas de salud posteriores. La mejoría inmediata de salud física no fue estadísticamente significativa.",limitation:"Programas de salud con varios apoyos, gran diversidad y limitaciones de diseño. Una pregunta sobre valores no reproduce el programa ni demuestra efectos para todas las metas."},{id:"M16",title:"Fogg · Instrucciones sobre gestos positivos de Tiny Habits",url:"https://tinyhabits.com/rewire/",type:"technique",finding:"Fogg recomienda un gesto positivo inmediato, elegido por ti, después de una acción muy pequeña.",limitation:"Página sobre un método práctico, sin estimación controlada. No se establecieron de forma independiente la necesidad de celebrar, conexiones neuronales más rápidas ni equivalencia con marcar una casilla."}],i=[{schemaVersion:2,revision:2,id:"motivation-1",courseId:"motivation",locale:"es",title:"¿Odias la tarea? Revisa la meta.",goal:"Decide si una meta vale su costo y prueba una acción que aporte a ella.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"¿Pesa la meta de tu lista? Revisa qué cambiaría ese esfuerzo en tu vida.",reason:{id:"motivation-1-reason",label:"¿Qué cambio en tu vida vale el costo semanal de esta meta?",kind:"text",maxLength:160,optional:!0,suggestions:["Abrir opciones para mi familia","Hacer espacio para mi curiosidad","Cumplir una responsabilidad que elijo"]},why:{id:"motivation-1-why",label:"¿Qué cambio en tu vida vale el costo semanal de esta meta?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Una tarea puede reflejar tus valores aunque no te guste hacerla. Estudiar para tener ingresos estables, cuidar a tu familia u obtener una certificación pueden ser elecciones propias. Disfrutar y hacer tuya una meta son preguntas distintas. Que otros la aprueben no significa automáticamente que la hayas tomado prestada.","Pregúntate qué cambiaría esa meta en tu vida diaria y cuánto tiempo o energía cuesta esta semana. Elige conservarla, cambiarla, aplazarla o dejarla. Si la conservas, prueba una acción útil en una ocasión viable. Vas a probar una elección; no a diagnosticar tus motivos verdaderos."],example:{title:"Lucía prueba una pregunta de estudio",text:"A las 7 p. m., Lucía sopesa su certificación y el tiempo familiar. No le gusta estudiar, pero valora las opciones laborales que podría abrirle. Conserva la meta y responde una pregunta de práctica en la mesa de la cocina. La respuesta queda incompleta. Registra el intento y elige otra ocasión, sin fingir que disfrutó estudiar."}},move:{invitation:"Elige la meta y concreta su acción antes de usar un ejemplo.",instructions:["Edita los ejemplos; elige cuidado, trabajo, vínculos o una acción propia.","Guarda una fecha disponible, señal de inicio y lugar para esa acción."],prompts:[{id:"motivation-1-0",label:"¿Qué estás eligiendo dejar de lado por esta meta?",kind:"text",maxLength:160,optional:!0}],suggestions:{action:["Ejemplo: responder la primera pregunta de mi certificación","Confirmar con Mariana cuándo recoger mañana","Escribir una frase del aviso para mi cliente","Hacer a Samuel la pregunta que acordamos"],minimum:["Responder esa pregunta de práctica","Enviar a Mariana la hora de recogida acordada","Escribir la primera frase útil del aviso","Preguntar cómo fue la cita de hoy"],cue:["Después de recoger mi plato de la cena","Cuando Mariana escriba sobre la recogida","Después del descanso laboral: 2 p. m.","Cuando empiece nuestra conversación nocturna acordada"],place:["En la mesa de mi cocina","En nuestro chat existente","En mi computadora de trabajo","En nuestra llamada habitual"],minutes:[2,1,5],fallback:["Responder una pregunta más corta de estas notas","Llamar por el medio que acordamos","Dictar esa frase en mis notas accesibles","Ofrecer la conversación por mensaje que acordamos"],observation:["Qué respondí y cuánto tiempo costó","Si envié la hora; la respuesta va aparte","Qué frase útil del aviso escribí","Pregunta hecha, incluso sin respuesta"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],bundles:[{action:"Ejemplo: responder la primera pregunta de mi certificación",minimum:"Responder esa pregunta de práctica",cue:"Después de recoger mi plato de la cena",place:"En la mesa de mi cocina",fallback:"Responder una pregunta más corta de estas notas",observation:"Qué respondí y cuánto tiempo costó",minutes:2},{action:"Confirmar con Mariana cuándo recoger mañana",minimum:"Enviar a Mariana la hora de recogida acordada",cue:"Cuando Mariana escriba sobre la recogida",place:"En nuestro chat existente",fallback:"Llamar por el medio que acordamos",observation:"Si envié la hora; la respuesta va aparte",minutes:1},{action:"Escribir una frase del aviso para mi cliente",minimum:"Escribir la primera frase útil del aviso",cue:"Después del descanso laboral: 2 p. m.",place:"En mi computadora de trabajo",fallback:"Dictar esa frase en mis notas accesibles",observation:"Qué frase útil del aviso escribí",minutes:5},{action:"Hacer a Samuel la pregunta que acordamos",minimum:"Preguntar cómo fue la cita de hoy",cue:"Cuando empiece nuestra conversación nocturna acordada",place:"En nuestra llamada habitual",fallback:"Ofrecer la conversación por mensaje que acordamos",observation:"Pregunta hecha, incluso sin respuesta",minutes:2}]},suggested:{action:"Ejemplo: responder la primera pregunta de mi certificación",minimum:"Responder esa pregunta de práctica",minutes:2,cueHint:"Después de recoger mi plato de la cena",placeHint:"En la mesa de mi cocina",obstacleHint:"Ejemplo: la pregunta de hoy compite con tiempo familiar",fallbackHint:"Responder una pregunta más corta de estas notas",observationHint:"Qué respondí y cuánto tiempo costó"},stopRule:"No te fuerces ante enfermedad, peligro o dificultades persistentes para funcionar. Puedes buscar apoyo ahora.",accessibleAlternative:"Usa audio, dictado, herramientas de apoyo, ayuda acordada o una pausa explícita."},result:{question:"¿Probaste la acción que elegiste hacer?",observationPrompt:"¿Qué hiciste realmente y qué costo tuvo para ti?"},judgment:{primary:{id:"motivation-1-decision",scenario:"A Lucía no le gusta estudiar para una certificación. Quiere opciones laborales más estables para su familia. Sus colegas también valoran esa credencial.",question:"¿Qué permite probar mejor si quiere conservarla?",options:[{id:"motivation-1-endorse",text:"Revisar si el beneficio y costo de tiempo reflejan su elección, y responder una pregunta de práctica.",feedback:"Esto distingue el desagrado de hacer propia la meta y prueba una acción viable. El reconocimiento puede convivir con una razón elegida. Puede cambiar o aplazar la meta si el costo no encaja."},{id:"motivation-1-interest",text:"Probar durante una semana una meta más agradable antes de decidir si esta certificación sigue siendo suya.",feedback:"Explorar otro interés puede servir, pero disfrutar no basta para decidir si esta certificación es propia. Examina primero el beneficio elegido y su costo; una tarea valiosa puede seguir siendo desagradable."},{id:"motivation-1-advice",text:"Preguntar a colegas certificados qué certificación elegirían y adoptar la que le recomienden.",feedback:"Los colegas pueden aclarar opciones y requisitos. Su recomendación no decide por Lucía lo que sacrificará. Necesita una razón propia y un costo de tiempo viable antes de adoptar esa meta."}],bestOptionId:"motivation-1-endorse"}},carry:{takeaway:"Una meta elegida puede costar trabajo. Valora su beneficio y costo; después prueba su acción.",followUp:{questionId:"motivation-1-return",question:"¿La prueba aportó a tu razón elegida y sigue valiendo la pena aceptar su costo?",observationPrompt:"¿Qué hiciste realmente y qué costo tuvo para ti?",adjustmentPrompt:"¿Qué cambio haría que tu próximo intento encaje?"}},goDeeper:{sections:[{heading:"Hacer tuya una meta no exige disfrutarla",paragraphs:["La teoría de autodeterminación de Ryan y Deci distingue disfrutar por interés propio de tener razones que haces tuyas. Una meta extrínseca puede tener valor: certificación, ingresos, cuidado o responsabilidad compartida pueden importar aunque la tarea aburra. Autonomía es sentir que eliges, sin exigir ausencia de obligaciones o influencias. Su artículo de 2000 es teoría y revisión narrativa, no un ensayo de esta lección. [M01]","La decisión de conservar, cambiar, aplazar o dejar una meta es un ejercicio de reflexión de ODA. No revela motivos puros ni certifica metas auténticas. El amplio metaanálisis de Cerasoli y colaboradores encontró que motivación intrínseca e incentivos pueden relacionarse con el desempeño, de formas distintas según calidad y cantidad. No demuestra que los premios sean siempre buenos o malos. [M04] Puedes reconocer motivos mezclados y decidir si esa acción aporta a la vida que quieres."]},{heading:"Una pregunta sobre valores no es todo un programa",paragraphs:["Ntoumanis y colaboradores combinaron 73 estudios de intervenciones de salud basadas en autodeterminación. Encontraron beneficios promedio modestos para motivación autónoma y conductas de salud posteriores. Los programas incluían varios apoyos; los resultados variaban mucho. La mejoría inmediata de salud física no fue estadísticamente significativa. Esto no demuestra el mismo beneficio para cada meta laboral, académica o personal. [M02]","Una pregunta sobre tu razón no reproduce esos programas. Aquí orienta una prueba práctica: una meta, una acción real, un registro honesto y otra ocasión. Usa la primera prueba para observar si encaja, si es accesible y cuánto cuesta, sin exigirte entusiasmo. Puedes conservar los detalles privados. Las próximas lecciones mantienen el mismo rumbo mientras prueban un mínimo útil, una señal que sirva y una respuesta a un obstáculo real. Pausar explícitamente o pedir apoyo es válido cuando la meta o las circunstancias requieren atención."]}],sourceIds:["M01","M04","M02"]}},{schemaVersion:2,revision:2,id:"motivation-2",courseId:"motivation",locale:"es",title:"¿Otra vez abriste el libro sin leer?",goal:"Prueba una versión pequeña de tu acción elegida que todavía produzca algo útil.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"¿Abriste el libro sin leer? Reduce la parte útil hasta que puedas hacerla.",reason:{id:"motivation-2-useful-unit-cost",label:"¿Qué preparación podrías dejar para hacer espacio a la parte útil?",kind:"text",maxLength:160,optional:!0,suggestions:["Dejar de abrir; leer una frase","Dejar de ordenar; escribir una frase","Conservar lo útil; reducir la cantidad"]},why:{id:"motivation-2-why",label:"¿Qué mínimo útil aportaría a la razón que elegiste?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Conserva la meta elegida. Reduce la acción hasta que quepa hoy, sin quitarle la parte útil. Acerca el libro y lee una frase. Abre la solicitud y escribe una frase útil. Preparar el lugar es preparación; la frase es la acción que quieres probar.","La investigación sobre hábitos describe respuestas repetidas en contextos recurrentes. No demuestra que todo inicio pequeño crezca ni que marcar una casilla tenga el mismo efecto que celebrar. Tu mínimo puede seguir siendo pequeño. Pruébalo, registra lo ocurrido y revisa después si esa cantidad todavía aporta a tu razón."],example:{title:"La pregunta más pequeña de Lucía",text:"El martes después de cenar, Lucía tiene dos minutos para la misma certificación. Acerca sus notas y responde una pregunta corta de práctica. Para ahí porque el tiempo familiar también importa. Su respuesta necesita una corrección. Registra la respuesta como trabajo y acercar las notas como preparación, sin alargar la sesión."}},move:{invitation:"Conserva tu acción guardada; reduce su parte útil antes de guardar.",instructions:["Conserva la acción y un entorno viable; cambia solo el mínimo útil.","Acerca los materiales necesarios y después realiza ese mínimo."],prompts:[],suggestions:{action:["Ejemplo: responder mi próxima pregunta de certificación","Escribir el párrafo guardado de mi solicitud","Hacer la limpieza de cocina acordada"],minimum:["Responder la primera parte de esa pregunta","Escribir una frase útil de ese párrafo","Lavar las dos tazas que acordamos"],cue:["Después de recoger mi plato de la cena","Después del descanso laboral: 2 p. m.","Después de terminar nuestra comida compartida"],place:["En la mesa de mi cocina","En mi computadora de trabajo","En el fregadero accesible de mi cocina"],minutes:[2,1],fallback:["Dictar la primera parte desde notas accesibles","Dictar una frase útil en mis notas","Elegir otra limpieza accesible acordada"],observation:["Respuesta real frente a materiales solo preparados","Frase escrita frente a archivo solo abierto","Tarea acordada hecha frente a materiales solo ordenados"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],bundles:[{action:"Ejemplo: responder mi próxima pregunta de certificación",minimum:"Responder la primera parte de esa pregunta",cue:"Después de recoger mi plato de la cena",place:"En la mesa de mi cocina",fallback:"Dictar la primera parte desde notas accesibles",observation:"Respuesta real frente a materiales solo preparados",minutes:2},{action:"Escribir el párrafo guardado de mi solicitud",minimum:"Escribir una frase útil de ese párrafo",cue:"Después del descanso laboral: 2 p. m.",place:"En mi computadora de trabajo",fallback:"Dictar una frase útil en mis notas",observation:"Frase escrita frente a archivo solo abierto",minutes:1},{action:"Hacer la limpieza de cocina acordada",minimum:"Lavar las dos tazas que acordamos",cue:"Después de terminar nuestra comida compartida",place:"En el fregadero accesible de mi cocina",fallback:"Elegir otra limpieza accesible acordada",observation:"Tarea acordada hecha frente a materiales solo ordenados",minutes:2}]},suggested:{action:"Ejemplo: responder mi próxima pregunta de certificación",minimum:"Responder la primera parte de esa pregunta",minutes:2,cueHint:"Después de recoger mi plato de la cena",placeHint:"En la mesa de mi cocina",obstacleHint:"Ejemplo: preparo los materiales sin responder",fallbackHint:"Dictar la primera parte desde notas accesibles",observationHint:"Respuesta real frente a materiales solo preparados"},stopRule:"Elige una acción segura. Para ante dolor, enfermedad, necesidades urgentes o un entorno inaccesible.",accessibleAlternative:"Escucha, dicta, usa herramientas de apoyo o registra preparación y fija una ocasión real posterior."},result:{question:"¿Hiciste la parte útil de tu mínimo?",observationPrompt:"¿Qué fue la acción real y qué fue solo preparación?"},judgment:{primary:{id:"motivation-2-decision",scenario:"Quieres escribir una solicitud. En tres sesiones abriste el archivo sin escribir nada. Tienes dos minutos y conoces la sección requerida.",question:"¿Qué mínimo prueba ahora un avance útil?",options:[{id:"motivation-2-bigger",text:"Reservar después una sesión más larga para sentir que vale la pena empezar una respuesta completa.",feedback:"Una sesión larga puede ayudar a terminar, pero deja sin probar el patrón actual de solo preparar. Escribe ahora una frase de borrador y decide después si necesitas más tiempo."},{id:"motivation-2-outline",text:"Usar los dos minutos para bosquejar tres puntos y escribir la sección requerida en una sesión más larga.",feedback:"Un esquema puede aclarar el contenido. Ya conoces esta sección y el obstáculo repetido es empezar a escribirla. Una frase de borrador lo prueba ahora; registra cualquier esquema como preparación."},{id:"motivation-2-sentence",text:"Escribir una frase de borrador para la sección requerida y parar al llegar al límite disponible.",feedback:"Esto contiene la acción y deja un texto editable. No garantiza que la solicitud tenga éxito ni exige alargar la sesión. Registra la frase aparte de abrir el archivo."}],bestOptionId:"motivation-2-sentence"}},carry:{takeaway:"Haz posible el inicio sin reducir tanto que desaparezca la acción útil.",followUp:{questionId:"motivation-2-return",question:"¿Tu versión pequeña produjo una acción útil o solo dejó listo el entorno?",observationPrompt:"¿Qué fue la acción real y qué fue solo preparación?",adjustmentPrompt:"¿Qué cambio haría que tu próximo intento encaje?"}},goDeeper:{sections:[{heading:"El tamaño pequeño es una elección, no una garantía",paragraphs:["Wood y Rünger describen los hábitos como respuestas aprendidas vinculadas a contextos recurrentes. Repetir puede apoyar una mayor automatización, mientras las metas deliberadas siguen importando. Su revisión no demuestra que una frase sea una dosis óptima ni que toda acción pequeña crezca inevitablemente. Esta lección usa una acción pequeña para probar su accesibilidad y utilidad en tu semana real. [M07]","Usa la acción para distinguir entre preparar y hacer la acción que quieres practicar. Puedes revisar una respuesta, aprender algo de una frase leída y editar una frase escrita. Tener materiales listos sirve, pero no contiene esas acciones. Si varios intentos pequeños nunca aportan a la razón elegida, revisa la acción o la meta. Quizá necesitas otra unidad, más apoyo o un espacio de tiempo mayor que sea viable. No conviertas marcar una casilla cómoda en progreso inventado. [M07]"]},{heading:"La receta del método tiene límites",paragraphs:["Las instrucciones de Tiny Habits de BJ Fogg unen una rutina existente y una acción muy pequeña. Recomiendan revisar las combinaciones que no funcionan. Es una técnica práctica propuesta por su autor. La página consultada no demuestra de forma independiente que toda la receta supere los planes de señales habituales ni que toda acción deba durar menos de un minuto. [M15]","Fogg también recomienda un gesto positivo inmediato, elegido por ti. La evidencia controlada del dossier no estableció las afirmaciones sobre conexiones neuronales más rápidas, celebrar necesariamente o marcar una casilla con el mismo efecto de refuerzo. [M16] Puedes notar satisfacción si aparece, sin fabricarla. Un registro honesto dice qué ocurrió, aparte de cómo te sentiste después. Puedes parar en el mínimo útil, mantenerlo mañana y adaptar herramientas o accesibilidad, sin interpretar una cantidad menor como un defecto de carácter."]}],sourceIds:["M07","M15","M16"]}},{schemaVersion:2,revision:2,id:"motivation-3",courseId:"motivation",locale:"es",title:"Sonó el recordatorio. Todavía no podías empezar.",goal:"Prueba tu mínimo con una señal que permita tiempo, materiales y accesibilidad.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"¿Suena el recordatorio mientras vas en autobús? Elige una señal con un entorno que sirva.",reason:{id:"motivation-3-available-setting-cost",label:"¿Qué entorno disponible usarás y qué moverás para proteger ese momento?",kind:"text",maxLength:160,optional:!0,suggestions:["Usar el descanso fijo que puedo proteger","Mover una tarea flexible","Asegurar el cuidado mientras practico"]},why:{id:"motivation-3-why",label:"¿Qué ocasión real protege tiempo para tu meta elegida?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Tu señal debe cumplir tres cosas: ocurrir, llamar tu atención y permitir la acción en ese momento. Después de llevar a los niños a la escuela no sirve para trabajar en un escritorio si vas directo al trabajo. Conserva el mínimo útil; elige un entorno que lo permita.","Los planes si-entonces concretos pueden ayudar a pasar de intención a acción. Repetir en un contexto recurrente puede apoyar un hábito, pero no hay una fecha final para todos. Prueba la señal, sin exigirte un hábito. Registra cuáles de sus tres funciones sirvieron y cuál necesita un cambio."],example:{title:"La ocasión viable de Lucía",text:"Lucía planeó su pregunta después de llevar a los niños a la escuela, pero fue directo al trabajo sin sus notas. El miércoles la mueve a después de cenar en la mesa de la cocina. La señal ocurre y ella la nota. Responde antes de recoger la mesa. Una respuesta es útil; la ocasión anterior sigue en su registro."}},move:{invitation:"Conserva tu acción; elige un evento y lugar disponibles.",instructions:["Revisa: ¿ocurre la señal, la notas y permite actuar?","Elige fecha y confirma los materiales o el acceso."],prompts:[],suggestions:{action:["Ejemplo: responder mi pregunta guardada de certificación","Escribir la frase guardada de mi solicitud","Hacer la limpieza de cocina acordada"],minimum:["Responder esa misma pregunta de práctica","Escribir esa misma frase útil","Lavar las mismas dos tazas acordadas"],cue:["Después de recoger mi plato de la cena","Al empezar mi descanso fijo: 12:30","Después de terminar nuestra comida compartida"],place:["En la mesa de mi cocina","En mi escritorio accesible durante el descanso","En el fregadero accesible de mi cocina"],minutes:[2,1],fallback:["Usar notas accesibles en la comida de mañana","Dictar la frase con mis notas guardadas","Próxima limpieza acordada, con ayuda para cuidar"],observation:["Ocurrió la señal, la noté y podía actuar","Si el entorno permitió la misma acción","Señal presente y tarea acordada posible"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],bundles:[{action:"Ejemplo: responder mi pregunta guardada de certificación",minimum:"Responder esa misma pregunta de práctica",cue:"Después de recoger mi plato de la cena",place:"En la mesa de mi cocina",fallback:"Usar notas accesibles en la comida de mañana",observation:"Ocurrió la señal, la noté y podía actuar",minutes:2},{action:"Escribir la frase guardada de mi solicitud",minimum:"Escribir esa misma frase útil",cue:"Al empezar mi descanso fijo: 12:30",place:"En mi escritorio accesible durante el descanso",fallback:"Dictar la frase con mis notas guardadas",observation:"Si el entorno permitió la misma acción",minutes:1},{action:"Hacer la limpieza de cocina acordada",minimum:"Lavar las mismas dos tazas acordadas",cue:"Después de terminar nuestra comida compartida",place:"En el fregadero accesible de mi cocina",fallback:"Próxima limpieza acordada, con ayuda para cuidar",observation:"Señal presente y tarea acordada posible",minutes:2}]},suggested:{action:"Ejemplo: responder mi pregunta guardada de certificación",minimum:"Responder esa misma pregunta de práctica",minutes:2,cueHint:"Después de recoger mi plato de la cena",placeHint:"En la mesa de mi cocina",obstacleHint:"Ejemplo: sonó la señal, pero no tenía notas",fallbackHint:"Usar notas accesibles en la comida de mañana",observationHint:"Ocurrió la señal, la noté y podía actuar"},stopRule:"No practiques al conducir ni cuando interfiera con el cuidado o la seguridad.",accessibleAlternative:"Usa recordatorios visibles o accesibles, audio, ayuda acordada o una señal posterior."},result:{question:"¿Tu señal permitió realizar el mínimo que elegiste?",observationPrompt:"¿Ocurrió la señal, la notaste y pudiste hacer la acción?"},judgment:{primary:{id:"motivation-3-usable-setting-decision",scenario:"Lucía quiere responder hoy su pregunta guardada. Su señal de llevar a los niños a la escuela falló porque el trabajo empieza enseguida. La cena ofrece cinco minutos confirmados con notas. Su descanso fijo de almuerzo permite una copia en el teléfono. El tren de mañana también permite estudiar, pero no tiene salida confirmada.",question:"¿Qué cambio prueba más directamente la misma acción hoy?",options:[{id:"motivation-3-dinner",text:"Usar el horario confirmado de la cena con sus notas actuales y responder la misma pregunta guardada.",feedback:"Esto cambia la ocasión no disponible y conserva acción y materiales. El horario está confirmado hoy. Registra si la señal ocurre, la nota y realmente permite responder."},{id:"motivation-3-phone-copy",text:"Hacer una copia en el teléfono al almorzar y responder la pregunta durante otro descanso disponible más adelante.",feedback:"Las notas portátiles podrían ayudar en descansos futuros. Esta elección dedica la ocasión conocida de hoy a preparar y deja sin fecha la respuesta. La cena prueba hoy la acción guardada con materiales disponibles."},{id:"motivation-3-train",text:"Llevar las notas para el tren de mañana y responder la misma pregunta cuando confirme la salida.",feedback:"El tren podría servir tras confirmar la salida. Pero aplaza la prueba aunque hoy hay una ocasión disponible. Si la cena deja de encajar, confirma la fecha del tren antes de comprometerte."}],bestOptionId:"motivation-3-dinner"}},carry:{takeaway:"Una señal útil ocurre, la notas y permite la acción en ese entorno.",followUp:{questionId:"motivation-3-return",question:"¿Qué falló con la señal: ocurrir, notarla o poder actuar?",observationPrompt:"¿Ocurrió la señal, la notaste y pudiste hacer la acción?",adjustmentPrompt:"¿Qué cambio haría que tu próximo intento encaje?"}},goDeeper:{sections:[{heading:"Una señal es una condición para probar",paragraphs:["La revisión de Gollwitzer y Sheeran de 2006 reunió 94 pruebas independientes de planes que unen una situación y una acción elegida. El logro de metas mejoró en promedio. El efecto estandarizado histórico de 0.65 no significa mejorar un 65 por ciento ni predice el efecto del recordatorio de tu app. Estos promedios históricos incluyen metas y entornos distintos, no esta señal exacta para estudiar. [M08]","Wood y Rünger describen la repetición vinculada al contexto como parte del aprendizaje de hábitos. Una señal sola no garantiza actuar, y no toda rutina es automática. [M07] ODA propone comprobar si ocurrió la señal, si la notaste y si podías actuar. Permite distinguir un recordatorio perdido de materiales no disponibles o una responsabilidad que compite. Si no hubo señal, registra «No hubo ocasión» cuando corresponda. Si hubo señal pero no actuaste, registra el hecho sin juzgar tu compromiso."]},{heading:"Sesenta y seis días fue una estimación",paragraphs:["El estudio de Lally de 2010 observó acciones diarias elegidas durante 84 días. Entre 39 participantes con curvas de automatización bien ajustadas, la mediana del tiempo estimado por el modelo para alcanzar el 95 por ciento de la meseta fue 66 días, con estimaciones de 18 a 254. La mayor superó el período observado. No eran fechas observadas del hábito terminado más rápido, promedio o más lento. [M05]","Tu práctica de certificación no copia las acciones de comer, beber o actividad física del estudio. No uses esa estimación como plazo ni como prueba de que practicar deba volverse fácil. Conserva la misma prueba y observa ocasiones disponibles, acciones útiles y el entorno que las facilitó. Una señal puede encajar entre semana y necesitar otro arreglo durante turnos o cuidados. Prueba un cambio deliberado y conserva el registro anterior para comparar condiciones reales al revisar."]}],sourceIds:["M08","M07","M05"]}},{schemaVersion:2,revision:2,id:"motivation-4",courseId:"motivation",locale:"es",title:"Planea para cuando suele fallar",goal:"Prueba una respuesta viable al obstáculo observado, protegiendo necesidades y responsabilidades reales.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"¿Estudias mientras toca acostar a tu hijo? Darte ánimos no consigue quién lo cuide.",reason:{id:"motivation-4-accepted-change-cost",label:"¿Qué cambio aceptarás para resolver el obstáculo registrado?",kind:"text",maxLength:160,optional:!0,suggestions:["Mover el horario; conservar la parte útil","Pedir apoyo concreto antes de darlo por hecho","Cambiar el acceso sin exigir más esfuerzo"]},why:{id:"motivation-4-why",label:"¿Qué necesita protección mientras avanzas con esta meta?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Conserva la meta y la parte útil. Revisa lo ocurrido: ¿cambiaste de tarea, faltaron materiales, alguien necesitaba cuidado o había una necesidad de salud? Combinar resultado, obstáculo y respuesta mostró beneficios promedio modestos. No crea tiempo ni ayuda.","Elige una respuesta acorde al problema. Una pestaña que distrae puede pedir otro entorno. Practicar mientras cuidas requiere ayuda acordada o un horario compatible. La enfermedad puede pedir descanso. Planea la primera acción útil que permita tu respuesta y pruébala en una ocasión adecuada. Ensayar es preparar; no demuestra que funcionó la alternativa."],example:{title:"Lucía consigue tiempo para estudiar",text:"La señal del jueves llega mientras Lucía acuesta a su hijo. Su pareja acuerda hacerse cargo durante cinco minutos después de acostarlo. Lucía mueve allí la misma pregunta y responde en la mesa mientras su pareja cuida. Registra el acuerdo y la respuesta. La pregunta necesita trabajo; no da por hecho la ayuda de mañana."}},move:{invitation:"Cambia la condición que falló; conserva la parte útil.",instructions:["Con ayuda acordada, prueba la misma acción; cambia solo el obstáculo registrado.","Sin acuerdo: «Adaptar este paso», «Apoyo». Pide ayuda concreta a alguien y acuerden cuándo.","Si rechazan la petición, usa otro horario disponible o pausa. Pedir apoyo es otra acción."],prompts:[{id:"motivation-4-support-request",label:"¿Qué ayuda pedirás, a quién y para cuándo?",kind:"text",maxLength:160,optional:!0,visible:!0,help:"Ejemplo: pedir a Mariana cinco minutos para cuidar por mensaje."}],suggestions:{action:["Ejemplo: escribir la frase guardada de mi solicitud","Responder mi pregunta guardada durante la ayuda acordada","Leer mi texto guardado con audio"],minimum:["Escribir esa misma frase útil de la solicitud","Responder esa misma pregunta de práctica","Escuchar ese mismo texto útil"],cue:["Después del descanso laboral: 2 p. m.","Al empezar cinco minutos acordados de ayuda","Al empezar mi descanso confirmado: 12:30"],place:["En mi computadora de trabajo","En la mesa de mi cocina","En mi espacio de descanso tranquilo y accesible"],minutes:[2,5],fallback:["Silenciar avisos opcionales; permitir contactos urgentes","Si falla la ayuda, pausar la práctica","Pedir una versión accesible si falla el audio"],observation:["Si hubo avisos y mi respuesta permitió escribir","Ayuda disponible y pregunta respondida van aparte","Acceso disponible y texto escuchado van aparte"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],bundles:[{action:"Ejemplo: escribir la frase guardada de mi solicitud",minimum:"Escribir esa misma frase útil de la solicitud",cue:"Después del descanso laboral: 2 p. m.",place:"En mi computadora de trabajo",fallback:"Silenciar avisos opcionales; permitir contactos urgentes",observation:"Si hubo avisos y mi respuesta permitió escribir",minutes:2},{action:"Responder mi pregunta guardada durante la ayuda acordada",minimum:"Responder esa misma pregunta de práctica",cue:"Al empezar cinco minutos acordados de ayuda",place:"En la mesa de mi cocina",fallback:"Si falla la ayuda, pausar la práctica",observation:"Ayuda disponible y pregunta respondida van aparte",minutes:2},{action:"Leer mi texto guardado con audio",minimum:"Escuchar ese mismo texto útil",cue:"Al empezar mi descanso confirmado: 12:30",place:"En mi espacio de descanso tranquilo y accesible",fallback:"Pedir una versión accesible si falla el audio",observation:"Acceso disponible y texto escuchado van aparte",minutes:5}]},suggested:{action:"Ejemplo: escribir la frase guardada de mi solicitud",minimum:"Escribir esa misma frase útil de la solicitud",minutes:2,cueHint:"Después del descanso laboral: 2 p. m.",placeHint:"En mi computadora de trabajo",obstacleHint:"Ejemplo: los avisos opcionales del teléfono interrumpieron mi última frase",fallbackHint:"Silenciar avisos opcionales; permitir contactos urgentes",observationHint:"Si hubo avisos y mi respuesta permitió escribir"},stopRule:"Asegura el cuidado y las urgencias. Elige apoyo o descanso ante enfermedad o situaciones inseguras.",accessibleAlternative:"Acuerda ayuda, cambia el acceso u horario o elige apoyo o descanso."},result:{question:"¿Tu respuesta permitió realizar el mínimo elegido?",observationPrompt:"¿Apareció el obstáculo y qué respuesta usaste cuando ocurrió?"},judgment:{primary:{id:"motivation-4-covered-slot-decision",scenario:"Practicar guitarra coincide con acostar al niño. Esta noche hay cinco minutos confirmados de ayuda; la guitarra está lista. Un vecino podría ayudar más tiempo el sábado, sin acordarlo. Quien cuida quiere probar hoy una frase musical breve sin descuidar al niño.",question:"¿Qué respuesta encaja mejor con ese próximo intento?",options:[{id:"motivation-4-confirmed-cover",text:"Tocar la frase breve durante los cinco minutos confirmados de ayuda esta noche y parar cuando terminen.",feedback:"El acuerdo aporta la condición faltante sin agrandar la acción. Toca la misma frase y registra la práctica aparte de la ayuda. El arreglo de esta noche no implica apoyo reservado después."},{id:"motivation-4-saturday-request",text:"Preguntar al vecino por el horario más largo del sábado y esperar confirmación antes de agendar esa práctica.",feedback:"Es una petición de apoyo segura para después. No prueba la frase breve ya viable esta noche. Elígela si esta noche deja de encajar. El sábado sigue sin confirmarse hasta acordarlo."},{id:"motivation-4-prepare-first",text:"Usar los cinco minutos de ayuda de esta noche para comprobar la afinación y marcar la frase para otra sesión.",feedback:"Afinar y marcar ayudan a preparar si hace falta. Aquí el instrumento y la frase están listos. Preparar otra vez deja la práctica sin probar; usa la ayuda confirmada para tocar."}],bestOptionId:"motivation-4-confirmed-cover"}},carry:{takeaway:"Una respuesta sirve si encaja con el obstáculo y deja protegidas las necesidades reales.",followUp:{questionId:"motivation-4-barrier-response-return",question:"¿Hiciste tu acción guardada y el cambio atendió el obstáculo registrado?",observationPrompt:"¿Qué fue práctica, qué fue apoyo y qué limitación seguía presente?",adjustmentPrompt:"¿Qué cambio haría que tu próximo intento encaje?"}},goDeeper:{sections:[{heading:"La investigación apoya los planes, con límites de duración",paragraphs:["La revisión de Wang y colaboradores de 2021 combinó 21 artículos y 24 efectos de contraste mental con planes si-entonces. El efecto promedio sobre alcanzar metas fue pequeño a moderado. Variaba según la meta y había señales de sesgo de publicación. Combinar resultado, obstáculo y respuesta no garantiza deseos, ni demuestra que pensar cambie acontecimientos externos ni establece que todos los formatos WOOP sean equivalentes. [M10]","Duckworth y colaboradores probaron un protocolo académico con 77 alumnos de quinto grado en una escuela. Trabajaron en grupos pequeños durante tres sesiones de una hora, con ejercicios repetidos y tarjetas recordatorias. Mejoraron algunos resultados académicos, pero las diferencias posteriores entre grupos no fueron significativas. [M03] El ejercicio breve de adultos de ODA cambia población, apoyos y duración. Es una adaptación para elegir una respuesta que puedas probar, no la intervención completa. Ensaya si sirve y distingue preparar de la ocasión real en que aparece el obstáculo y necesitas la respuesta."]},{heading:"Atiende el obstáculo sin culpar a la persona",paragraphs:["El procedimiento considera un resultado deseado, un obstáculo y una respuesta elegida. No establece que todo obstáculo sea una actitud interna. El cuidado, dinero, accesibilidad por discapacidad, turnos, enfermedad y conductas dañinas ajenas pueden limitar lo viable. Una respuesta práctica puede ser apoyo acordado, cambiar horarios, una adaptación, descanso o un límite. La versión para adultos debe nombrar esas limitaciones con honestidad. [M03, M10]","Usa tu registro real para elegir una condición que cambiar. Si hubo señal pero faltaban materiales, comprometerte más no atiende el problema. Si necesitaban tu cuidado, asegúrate de que alguien se haga cargo. Si apareció un hábito distractor, prueba una respuesta que permita contactos urgentes. Un obstáculo que no apareció deja la alternativa sin probar. Registra la parte útil aparte de organizar ayuda o mover materiales. Después, conserva el entorno que funcionó sin acumular rituales ni exigir más ganas."]}],sourceIds:["M10","M03"]}},{schemaVersion:2,revision:2,id:"motivation-5",courseId:"motivation",locale:"es",title:"¿Perdiste un día? Planea cómo retomar.",goal:"Revisa la misma prueba, conserva una condición útil y agenda el próximo intento viable.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"¿Perdiste sesiones? ¿Cambió tu meta o el tiempo disponible?",reason:{id:"motivation-5-reason",label:"¿Esta meta todavía merece espacio la próxima semana?",kind:"text",maxLength:160,optional:!0,suggestions:["Volver a una meta que aún elijo","Cambiar una señal que ya no encaja","Proteger el descanso y pedir apoyo"]},why:{id:"motivation-5-why",label:"¿Esta meta todavía merece espacio la próxima semana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Revisa la razón elegida, mínimo útil, señal y registros reales. Seguir el progreso puede ayudar a alcanzar metas en promedio. No convierte un plan sin probar en acción ni un historial vacío en fracaso. Distingue preparación, trabajo realizado y pausa al decidir qué ayudó.","En un estudio, perder una ocasión no alteró sustancialmente la formación de hábitos. Eso no demuestra que interrupciones largas sean inocuas. Repite un entorno que sirvió, cambia una ocasión no disponible o reconsidera la meta. Fija fecha para la siguiente parte útil. No necesitas duplicar el esfuerzo ni ganarte permiso para descansar."],example:{title:"La próxima ocasión de Lucía",text:"El domingo, Lucía revisa el mismo plan de certificación. Dos horarios de cena sirvieron; un cambio de turno bloqueó otros dos. Sigue eligiendo la meta y mueve una pregunta al descanso disponible del lunes con notas accesibles. Anota la próxima ocasión. Las sesiones perdidas siguen perdidas. La acción del lunes todavía es un plan."}},move:{invitation:"Revisa el registro; programa la misma acción útil en una ocasión disponible.",instructions:["Cambia solo la condición que señalan tus intentos; confirma su fecha y entorno.","Se agendan este intento y su revisión al día siguiente. Revisar semanalmente es opcional."],prompts:[],suggestions:{action:["Ejemplo: responder mi pregunta guardada de certificación","Hacer mi caminata corta guardada","Hacer la limpieza de cocina acordada"],minimum:["Responder esa misma pregunta de práctica","Caminar la misma ruta segura de cinco minutos","Lavar las mismas dos tazas acordadas"],cue:["Inicio del descanso de almuerzo confirmado, 12:30","Cuando empiece mi descanso fijo del mediodía","Después de terminar nuestra comida compartida"],place:["En mi escritorio accesible durante el descanso","En mi circuito accesible del trabajo","En el fregadero accesible de mi cocina"],minutes:[2,5],fallback:["Si cancelan el almuerzo, programar otro momento","Si la ruta es insegura, elegir movimiento sentado","Si no se puede, acordar otra limpieza útil"],observation:["Si la nueva ocasión permitió la misma pregunta","Movimiento real y tiempo disponible","Tarea hecha y si encajó el entorno"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],bundles:[{action:"Ejemplo: responder mi pregunta guardada de certificación",minimum:"Responder esa misma pregunta de práctica",cue:"Inicio del descanso de almuerzo confirmado, 12:30",place:"En mi escritorio accesible durante el descanso",fallback:"Si cancelan el almuerzo, programar otro momento",observation:"Si la nueva ocasión permitió la misma pregunta",minutes:2},{action:"Hacer mi caminata corta guardada",minimum:"Caminar la misma ruta segura de cinco minutos",cue:"Cuando empiece mi descanso fijo del mediodía",place:"En mi circuito accesible del trabajo",fallback:"Si la ruta es insegura, elegir movimiento sentado",observation:"Movimiento real y tiempo disponible",minutes:5},{action:"Hacer la limpieza de cocina acordada",minimum:"Lavar las mismas dos tazas acordadas",cue:"Después de terminar nuestra comida compartida",place:"En el fregadero accesible de mi cocina",fallback:"Si no se puede, acordar otra limpieza útil",observation:"Tarea hecha y si encajó el entorno",minutes:2}]},suggested:{action:"Ejemplo: responder mi pregunta guardada de certificación",minimum:"Responder esa misma pregunta de práctica",minutes:2,cueHint:"Inicio del descanso de almuerzo confirmado, 12:30",placeHint:"En mi escritorio accesible durante el descanso",obstacleHint:"Ejemplo: mi cambio de turno registrado quitó el tiempo nocturno de estudio",fallbackHint:"Si cancelan el almuerzo, programar otro momento",observationHint:"Si la nueva ocasión permitió la misma pregunta"},stopRule:"La pérdida persistente de interés o dificultades para funcionar merecen apoyo ahora. Ante peligro inmediato, busca ayuda urgente.",accessibleAlternative:"Usa materiales accesibles, ayuda acordada, una petición de apoyo, descanso o una pausa explícita."},result:{question:"¿Realizaste la acción elegida para retomar?",observationPrompt:"¿Qué acción real, apoyo o pausa registraste esta vez?"},judgment:{primary:{id:"motivation-5-recorded-barrier-decision",scenario:"El nuevo turno de Diego empieza antes de terminar la cena y elimina su caminata nocturna. Sigue eligiendo caminar. Tiene una ruta segura diaria de cinco minutos al almorzar. Otra ruta segura antes del turno exige levantarse temprano; el domingo hay una más larga. Quiere probar retomar entre semana sin dormir menos.",question:"¿Qué plan encaja mejor con el obstáculo registrado y su costo?",options:[{id:"motivation-5-early-walk",text:"Caminar antes del turno y poner una alarma más temprano para proteger esa nueva ocasión.",feedback:"La ruta antes del turno resuelve el conflicto nocturno, pero adelantar la alarma contradice su límite de sueño. El almuerzo disponible permite probar entre semana sin ese costo adicional."},{id:"motivation-5-sunday-walk",text:"Cambiar a una caminata dominical más larga y reconsiderar si una frecuencia semanal encaja mejor con su horario.",feedback:"Caminar semanalmente es un cambio viable de meta, no un fracaso. Diego quiere probar entre semana y tiene el almuerzo disponible. Prueba esa condición antes de cambiar la frecuencia."},{id:"motivation-5-lunch-return",text:"Elegir cuándo almorzará, caminar los cinco minutos seguros y registrar si encaja el nuevo horario.",feedback:"Esto conserva caminar y su parte útil, resolviendo el horario nocturno no disponible. Solo la caminata real cuenta como práctica. La revisión de mañana puede orientar repetir, cambiar o terminar este arreglo."}],bestOptionId:"motivation-5-lunch-return"}},carry:{takeaway:"Conserva la razón y acción útil; cambia la condición que tu registro muestra que falló.",followUp:{questionId:"motivation-5-return",question:"¿La nueva ocasión encajó y sigue valiendo la meta su costo la próxima semana?",observationPrompt:"¿Qué acción real, apoyo o pausa registraste esta vez?",adjustmentPrompt:"¿Qué cambio haría que tu próximo intento encaje?"}},goDeeper:{sections:[{heading:"Consolida los hechos sin inventar una racha",paragraphs:["La revisión de Harkin y colaboradores de 138 estudios aleatorizados encontró beneficios promedio para las metas al seguir el progreso. Variaron metas y métodos. Registrar y comunicar resultados se asociaron con efectos mayores en análisis de moderadores, pero eso no demuestra que sea necesario compartir públicamente ni revisar semanalmente. La revisión al día siguiente de ODA es una adaptación, no una dosis validada. Revisar semanalmente es opcional; este plan no lo agenda automáticamente. [M13]","El estudio observacional de Lally encontró que perder una ocasión no alteró sustancialmente su proceso modelado de formación de hábitos. Ese resultado limitado no prueba que las interrupciones largas no afecten el hábito. [M05] Usa tus intentos para decidir qué sigue. Conserva una parte útil, cambia una señal o respuesta que no encajó y deja visibles las ocasiones perdidas. Un plan futuro sigue siendo un plan. Si la meta ya no vale el tiempo que cuesta, cámbiala, aplázala o termínala deliberadamente. Terminar el aprendizaje sigue separado de hacer y revisar la acción."]},{heading:"Disfrutar es opcional; puedes pedir apoyo ahora",paragraphs:["Esta última lección consolida la prueba sin añadir otro ritual motivador. La investigación sobre seguimiento respalda beneficios promedio de comparar progreso real y meta elegida, pero no identifica la mejor técnica para cada persona. Tu registro puede mostrar una señal no disponible, materiales faltantes o un costo de tiempo que ya no encaja. Usa esa condición observada para elegir el próximo cambio. No cuentes preparar o prometer como hacer la acción. [M13]","No condiciones el descanso básico ni toda actividad placentera a la productividad. Si después eliges audio gratuito compatible, mantén la atención al tráfico y la seguridad. Pérdida persistente de interés, malestar, agotamiento o dificultades con actividades habituales pueden requerir evaluación profesional. La guía del NIMH respalda buscar ayuda y atención inmediata ante peligro urgente; no diagnostica la causa desde la poca motivación ni exige esperar para pedir ayuda. [M20] Puedes conservar una práctica pequeña útil, pedir apoyo o pausar mientras atiendes esa preocupación."]}],sourceIds:["M13","M05","M20"]}}];function o(a,r,c){const n=a.judgment.primary,e=[...n.options],t=e.findIndex(s=>s.id===n.bestOptionId);return[e[r],e[t]]=[e[t],e[r]],{id:a.id,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,practice:[a.move.instructions[0],a.move.instructions[1],"Registra lo que pasó realmente. Mañana revisa el mismo intento."],reflection:a.direction.reason.label,question:`${n.scenario} ${n.question}`,options:e.map(s=>s.text),correct:r,feedback:e[r].feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds,photo:c}}const l={id:"motivation",title:"¿Esperas motivación? Hazle espacio a tu meta hoy.",subtitle:"Cinco lecciones: elige una meta que valga su costo, prueba un mínimo útil y adapta el entorno a tu semana.",description:"Elige para qué sirve el esfuerzo, haz una versión pequeña útil y ajusta la señal o el apoyo según lo que ocurrió realmente.",scope:"Práctica para metas cotidianas. La falta constante de ganas, el agotamiento o perder la capacidad de funcionar pueden ir más allá de la motivación. Conviene buscar apoyo; un profesional de salud puede ayudarte a entender la causa.",outcome:"Una acción elegida y un próximo intento con fecha, ajustados según tus registros.",photo:{id:"1790004245013-b347139d5591",alt:"Hombre corriendo por un sendero de bosque soleado"},lang:"es",lessons:[o(i[0],1,{id:"1517971129774-8a2b38fa128e",alt:"Mujer escribiendo en un cuaderno junto a una ventana"}),o(i[1],2,{id:"1581578731509-8ae9c5a3e7d3",alt:"Un par de zapatos junto a la puerta"}),o(i[2],2,{id:"1499933374294-4584851497cc",alt:"Reloj despertador negro sobre una mesa"}),o(i[3],1,{id:"1575478004055-999ebe26dab7",alt:"Mujer caminando bajo la lluvia con paraguas"}),o(i[4],0,{id:"1577950248429-7530424d9682",alt:"Calendario mensual colgado en un tablero"})]},u=Object.freeze(Object.defineProperty({__proto__:null,COURSE:l,LESSONS_V2:i,SOURCES:d},Symbol.toStringTag,{value:"Module"}));export{u as m};
